UPDATE book_inventory
SET status = 'BORROWED',
updated_by = #{updatedBy}
WHERE id = #{inventoryId}
AND status = 'AVAILABLE'
AND is_deleted = 0

UPDATE book_loans
SET return_date = #{returnDate},
updated_by = #{updatedBy}
WHERE id = #{loanId}
AND return_date IS NULL
AND is_deleted = 0

UPDATE book_inventory
SET status = 'AVAILABLE',
updated_by = #{updatedBy}
WHERE id = #{inventoryId}
AND status = 'BORROWED'
AND is_deleted = 0
